import sys, collections
sys.path.insert(0,'scripts/research'); sys.path.insert(0,'scripts')
import retrieval_log as r
c=collections.Counter(); by={}
for d in sorted(p for p in r.LOG_ROOT.iterdir() if p.is_dir()):
    for rec in r._manifest_records(d.name):
        if rec.get('derived'):
            nm=rec.get('artefact','')
            c[(nm.rsplit('-',1)[-1] if '-' in nm else nm[-8:], rec.get('content_type'), bool(rec.get('ref_id')), (d/nm).is_file())]+=1
            if rec.get('ref_id'): by.setdefault(rec['ref_id'],[]).append((d.name,nm,rec.get('content_type')))
for k,v in c.items(): print(k,v)
for k,v in by.items():
    print(k, [(n, ct) for s,n,ct in v], r.decodable_body_artefacts(k))
